//! Build script: parse the TypeSpec-generated `openapi.yaml` and emit
//! Rust types from its `components.schemas` section.
//!
//! The generated module lands at `$OUT_DIR/typespec_types.rs` and is
//! pulled in via `include!` from `src/lib.rs`. No Node.js is required
//! at Rust build time: the openapi.yaml is committed to the
//! `typespec-poc/tsp-output/` directory and acts as the cached
//! intermediate between the `.tsp` source of truth and the Rust types.
//!
//! Workflow:
//!
//! 1. Editor changes a `.tsp` file in `typespec-poc/`.
//! 2. Editor runs `npm run build` in that directory; this regenerates
//!    `tsp-output/openapi3/openapi.yaml` (and the `.proto` files).
//! 3. Editor commits both the `.tsp` change and the regenerated
//!    `tsp-output/`. CI runs `verify.ps1` to assert the cache is in
//!    sync with the source `.tsp` files.
//! 4. The next `cargo build` of `mumble-file-server-types` re-runs
//!    this script (because of the `rerun-if-changed` line), parses
//!    the new YAML, and emits new Rust types.

use std::{env, fs, path::PathBuf};

use schemars::schema::RootSchema;
use serde_json::Value;
use typify::{TypeSpace, TypeSpaceSettings};

const OPENAPI_REL_PATH: &str =
    "../file-server/typespec-poc/tsp-output/openapi3/openapi.yaml";

fn main() {
    println!("cargo:rerun-if-changed={OPENAPI_REL_PATH}");
    println!("cargo:rerun-if-changed=build.rs");

    let yaml = fs::read_to_string(OPENAPI_REL_PATH)
        .unwrap_or_else(|e| panic!("read {OPENAPI_REL_PATH}: {e}"));
    let mut doc: Value =
        serde_yml::from_str(&yaml).expect("openapi.yaml is not valid YAML");

    // Pull components.schemas out and rewrite OpenAPI-style refs into
    // schemars/typify-style refs.
    let schemas = doc
        .pointer_mut("/components/schemas")
        .and_then(Value::as_object_mut)
        .expect("openapi.yaml has no components.schemas");
    let schemas_owned = std::mem::take(schemas);
    let mut wrapper = serde_json::json!({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "definitions": schemas_owned,
    });
    rewrite_refs(&mut wrapper);

    let root: RootSchema = serde_json::from_value(wrapper)
        .expect("synthesised RootSchema failed to deserialise");

    let mut type_space = TypeSpace::new(&TypeSpaceSettings::default());
    type_space
        .add_ref_types(root.definitions)
        .expect("typify failed to ingest definitions");

    let header = "// @generated by mumble-file-server-types/build.rs\n\
                  // Do NOT edit by hand. Regenerate by editing the .tsp\n\
                  // source in ../file-server/typespec-poc/ and running\n\
                  // `npm run build` in that directory.\n\n";
    let parsed = syn::parse2::<syn::File>(type_space.to_stream())
        .expect("typify produced syntactically invalid Rust");
    let body = prettyplease::unparse(&parsed);

    let out_dir = PathBuf::from(env::var_os("OUT_DIR").expect("OUT_DIR set"));
    let out_path = out_dir.join("typespec_types.rs");
    fs::write(&out_path, format!("{header}{body}"))
        .unwrap_or_else(|e| panic!("write {}: {e}", out_path.display()));
}

/// Recursively rewrite every `$ref: "#/components/schemas/X"` to
/// `$ref: "#/definitions/X"` so the OpenAPI 3.1 component table can
/// be parsed as a schemars draft-07 RootSchema.
fn rewrite_refs(value: &mut Value) {
    match value {
        Value::Object(map) => {
            if let Some(Value::String(s)) = map.get_mut("$ref") {
                if let Some(rest) = s.strip_prefix("#/components/schemas/") {
                    *s = format!("#/definitions/{rest}");
                }
            }
            for v in map.values_mut() {
                rewrite_refs(v);
            }
        }
        Value::Array(arr) => {
            for v in arr {
                rewrite_refs(v);
            }
        }
        _ => {}
    }
}
